args.sparql:
SELECT ?prop ?obj ?label WHERE {
  VALUES ?prop { dbp:parents dbp:parent dbp:mother dbp:father dbo:parent dbo:mother dbo:father }
  dbr:Sara_Ali_Khan ?prop ?obj .
  OPTIONAL { ?obj rdfs:label ?label . FILTER(lang(?label) = "en") }
}

SELECT DISTINCT ?step ?stepLabel WHERE {
  dbr:Saif_Ali_Khan dbo:spouse ?step .
  ?step a dbo:Person .
  dbr:Saif_Ali_Khan dbo:child dbr:Sara_Ali_Khan .
  FILTER(?step != dbr:Amrita_Singh)
  OPTIONAL { ?step rdfs:label ?stepLabel FILTER(lang(?stepLabel) = "en") }
}

